// Mock Backend Service for Banner Management
// This simulates a real backend API for development/testing purposes

class MockBackendService {
  constructor() {
    // Initialize with some sample banners
    this.banners = [
      {
        _id: "1",
        title: "Welcome to PowerFuel",
        description: "Discover premium supplements for your fitness journey",
        image: "https://images.unsplash.com/photo-1571019613454-1cb2f99b2d8b?w=800&h=400&fit=crop",
        link: "/products",
        buttonText: "Shop Now",
        order: 1,
        isActive: true,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString()
      },
      {
        _id: "2",
        title: "Protein Power",
        description: "High-quality protein supplements for muscle growth and recovery",
        image: "https://images.unsplash.com/photo-1556909114-f6e7ad7d3136?w=800&h=400&fit=crop",
        link: "/products?category=protein",
        buttonText: "Explore Protein",
        order: 2,
        isActive: true,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString()
      }
    ];

    this.nextId = 3;
  }

  // Simulate API delay
  async delay(ms = 300) {
    return new Promise(resolve => setTimeout(resolve, ms));
  }

  // Get all banners
  async getAllBanners() {
    await this.delay();
    return {
      success: true,
      data: this.banners.sort((a, b) => a.order - b.order)
    };
  }

  // Get active banners only
  async getActiveBanners() {
    await this.delay();
    const activeBanners = this.banners.filter(banner => banner.isActive);
    return {
      success: true,
      data: activeBanners.sort((a, b) => a.order - b.order)
    };
  }

  // Get banner by ID
  async getBannerById(id) {
    await this.delay();
    const banner = this.banners.find(b => b._id === id);
    if (!banner) {
      throw new Error("Banner not found");
    }
    return {
      success: true,
      data: banner
    };
  }

  // Create new banner
  async createBanner(bannerData) {
    await this.delay();

    // Validate required fields
    if (!bannerData.title || !bannerData.description || !bannerData.image) {
      throw new Error("Title, description, and image are required");
    }

    const newBanner = {
      _id: this.nextId.toString(),
      ...bannerData,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };

    this.banners.push(newBanner);
    this.nextId++;

    return {
      success: true,
      data: newBanner,
      message: "Banner created successfully"
    };
  }

  // Update banner
  async updateBanner(id, updateData) {
    await this.delay();

    const bannerIndex = this.banners.findIndex(b => b._id === id);
    if (bannerIndex === -1) {
      throw new Error("Banner not found");
    }

    this.banners[bannerIndex] = {
      ...this.banners[bannerIndex],
      ...updateData,
      updatedAt: new Date().toISOString()
    };

    return {
      success: true,
      data: this.banners[bannerIndex],
      message: "Banner updated successfully"
    };
  }

  // Delete banner
  async deleteBanner(id) {
    await this.delay();

    const bannerIndex = this.banners.findIndex(b => b._id === id);
    if (bannerIndex === -1) {
      throw new Error("Banner not found");
    }

    this.banners.splice(bannerIndex, 1);

    return {
      success: true,
      message: "Banner deleted successfully"
    };
  }

  // Toggle banner status
  async toggleBannerStatus(id) {
    await this.delay();

    const banner = this.banners.find(b => b._id === id);
    if (!banner) {
      throw new Error("Banner not found");
    }

    banner.isActive = !banner.isActive;
    banner.updatedAt = new Date().toISOString();

    return {
      success: true,
      data: banner,
      message: `Banner ${banner.isActive ? 'activated' : 'deactivated'} successfully`
    };
  }
}

// Create singleton instance
const mockBackend = new MockBackendService();

export default mockBackend;
